namespace VMLRuntime.Device
{
    /// <summary>
    /// CP437（IBM PC 原始字符集）高半区 `0x80`–`0xFF` → Unicode 的映射。
    ///
    /// <para>
    /// **为什么运行时需要这张表**：老程序（DOS/Turbo C 时代）画框线时写的是**裸字节** ——
    /// `0xC4` 是 `─`、`0xDA` 是 `┌`、`0xB3` 是 `│`。那些字节**不是** UTF-8：
    /// 它们落在 UTF-8 的**首字节区间**（`0xC0`–`0xDF` 两字节、`0xE0`–`0xEF` 三字节），
    /// 于是解码器会把**下一个字节**当成续字节一起吃掉，拼出一个 U+FFFD。
    /// 实测（`putchar(0xC4)` ×3）：输出 `EF BF BD` ×3 —— 框线全变成 `�`，
    /// 而且**字节数对不上**（3 个字节有时出 2 个替换符），整幅画面错位。
    /// </para>
    ///
    /// <para>
    /// **判据是「先按 UTF-8 严格验，验不过就按单字节」**（见
    /// <c>VMLRuntime.Syscall.cs</c> 的 <c>TryFlushOneUtf8Unit</c>）：
    /// 合法的 UTF-8 照旧走多字节路径（中文输出一字不变），
    /// 不合法的**只吐第一个字节**、绝不吞掉后面那个 —— 后者才是症状的根源。
    /// 单字节那一个用这张表翻译成 CP437 字符。
    /// </para>
    ///
    /// <para>
    /// 表格是**手写常量**：AOT 下 `Encoding.GetEncoding(437)` 需要额外的
    /// `System.Text.Encoding.CodePages` 包 + 注册，而这里只有 128 项、一次性查表，
    /// 不值得为它引一个依赖（也符合本仓"零反射、AOT 安全"的约束）。
    /// </para>
    /// </summary>
    public static class Cp437
    {
        /// <summary>`0x80`–`0xFF` 对应的 Unicode 码点（下标 = 字节值 − 0x80）。</summary>
        private static readonly char[] High =
        {
            'Ç', 'ü', 'é', 'â', 'ä', 'à', 'å', 'ç', // 80-87
            'ê', 'ë', 'è', 'ï', 'î', 'ì', 'Ä', 'Å', // 88-8F
            'É', 'æ', 'Æ', 'ô', 'ö', 'ò', 'û', 'ù', // 90-97
            'ÿ', 'Ö', 'Ü', '¢', '£', '¥', '₧', 'ƒ', // 98-9F
            'á', 'í', 'ó', 'ú', 'ñ', 'Ñ', 'ª', 'º', // A0-A7
            '¿', '⌐', '¬', '½', '¼', '¡', '«', '»', // A8-AF
            '░', '▒', '▓', '│', '┤', '╡', '╢', '╖', // B0-B7
            '╕', '╣', '║', '╗', '╝', '╜', '╛', '┐', // B8-BF
            '└', '┴', '┬', '├', '─', '┼', '╞', '╟', // C0-C7
            '╚', '╔', '╩', '╦', '╠', '═', '╬', '╧', // C8-CF
            '╨', '╤', '╥', '╙', '╘', '╒', '╓', '╫', // D0-D7
            '╪', '┘', '┌', '█', '▄', '▌', '▐', '▀', // D8-DF
            'α', 'ß', 'Γ', 'π', 'Σ', 'σ', 'µ', 'τ', // E0-E7
            'Φ', 'Θ', 'Ω', 'δ', '∞', 'φ', 'ε', '∩', // E8-EF
            '≡', '±', '≥', '≤', '⌠', '⌡', '÷', '≈', // F0-F7
            '°', '∙', '·', '√', 'ⁿ', '²', '■', '\u00A0', // F8-FF（FF 是不间断空格）
        };

        /// <summary>把**一个** CP437 字节翻成对应的 Unicode 字符（`0x00`–`0x7F` 原样）。</summary>
        public static char ToChar(byte b) => b < 0x80 ? (char)b : High[b - 0x80];
    }
}
